-- Isolated fixture for migration 029 (synthetic rows only; never real students). Run BEFORE 029.
create schema if not exists auth;
do $$ begin create role authenticated nologin; exception when duplicate_object then null; end $$;
do $$ begin create role anon nologin; exception when duplicate_object then null; end $$;
create table auth.users(id uuid primary key);
create or replace function auth.uid() returns uuid language sql stable as
$$ select nullif(current_setting('test.actor', true), '')::uuid $$;
grant usage on schema auth, public to authenticated, anon;
grant execute on function auth.uid() to authenticated, anon;

create table public.profiles(id uuid primary key,role text not null,is_active boolean not null default true);
create table public.branches(id uuid primary key);
create table public.programmes(id uuid primary key);
create table public.students(id uuid primary key,full_name text not null,status text not null default 'active');
create table public.enrollments(
 id uuid primary key,student_id uuid references public.students(id),
 branch_id uuid references public.branches(id),programme_id uuid references public.programmes(id),
 default_session_id uuid,start_date date not null,end_date date,status text not null
);
create table public.schedule_batches(
 id uuid primary key,branch_id uuid not null references public.branches(id),
 schedule_month date not null,status text not null,
 approved_at timestamptz,updated_at timestamptz not null default now()
);
create table public.class_sessions(
 id uuid primary key,schedule_batch_id uuid not null references public.schedule_batches(id) on delete cascade,
 session_template_id uuid not null,branch_id uuid not null references public.branches(id),
 programme_id uuid not null references public.programmes(id),
 class_date date not null,start_time time not null,end_time time not null,
 regular_capacity integer not null,status text not null default 'scheduled'
);
create table public.student_bookings(
 id uuid primary key default gen_random_uuid(),class_session_id uuid not null references public.class_sessions(id) on delete cascade,
 student_id uuid not null references public.students(id),
 enrollment_id uuid references public.enrollments(id),
 booking_type text not null,attendance_status text not null,
 updated_at timestamptz not null default now(),
 unique(class_session_id,student_id)
);
create table public.makeup_obligations(
 id uuid primary key default gen_random_uuid(),
 source_booking_id uuid not null references public.student_bookings(id),
 target_booking_id uuid references public.student_bookings(id)
);
grant select on public.profiles, public.students, public.enrollments, public.class_sessions,
 public.schedule_batches, public.student_bookings to authenticated;
-- The RPCs are SECURITY DEFINER; direct client writes are NOT granted (tested).

